[] a sh:ValidationReport ;
    sh:conforms false ;
    sh:result [ a sh:ValidationResult ;
            sh:focusNode [ a schema1:DataDownload ;
                    dcterms:conformsTo <http://www.opengis.net/def/nil/OGC/0/missing> ;
                    schema1:encodingFormat "text/csv" ;
                    schema1:name "Water levels in Beartooth reservoir, 1992-2020" ;
                    schema1:provider <https://orcid.org/3333-4444-5565> ;
                    ns1:checksum [ a ns1:Checksum ;
                            ns1:algorithm "MD5" ;
                            ns1:checksumValue "d41d8cd98f00b204e9800998ecf8427e" ] ] ;
            sh:resultMessage "Less than 1 values on [ dcterms:conformsTo <http://www.opengis.net/def/nil/OGC/0/missing> ; ns1:checksum [ ns1:algorithm Literal(\"MD5\") ; ns1:checksumValue Literal(\"d41d8cd98f00b204e9800998ecf8427e\") ; rdf:type ns1:Checksum ] ; rdf:type schema1:DataDownload ; schema1:encodingFormat Literal(\"text/csv\") ; schema1:name Literal(\"Water levels in Beartooth reservoir, 1992-2020\") ; schema1:provider <https://orcid.org/3333-4444-5565> ]->schema1:contentUrl" ;
            sh:resultPath schema1:contentUrl ;
            sh:resultSeverity sh:Violation ;
            sh:sourceConstraintComponent sh:MinCountConstraintComponent ;
            sh:sourceShape [ sh:datatype xsd:string ;
                    sh:minCount 1 ;
                    sh:path schema1:contentUrl ;
                    sh:pattern "^[a-zA-Z][a-zA-Z0-9+.-]*:[^\\s]*$" ] ] .

